CREATE TABLE IF NOT EXISTS "active_orders" (
	"id" INTEGER NOT NULL UNIQUE GENERATED BY DEFAULT AS IDENTITY,
	PRIMARY KEY("id")
);




CREATE TABLE IF NOT EXISTS "archive_orders" (
	"id" INTEGER NOT NULL UNIQUE GENERATED BY DEFAULT AS IDENTITY,
	PRIMARY KEY("id")
);




CREATE TABLE IF NOT EXISTS "orders" (
	"id" INTEGER NOT NULL UNIQUE GENERATED BY DEFAULT AS IDENTITY,
	"car_id" INTEGER NOT NULL,
	"client_id" INTEGER NOT NULL,
	"status" VARCHAR(20) NOT NULL,
	"creation_time" TIMESTAMP NOT NULL DEFAULT NOW(),
	PRIMARY KEY("id")
);




CREATE TABLE IF NOT EXISTS "cars" (
	"id" INTEGER NOT NULL UNIQUE GENERATED BY DEFAULT AS IDENTITY,
	"state_number" VARCHAR(10) NOT NULL,
	"vin" VARCHAR(17) NOT NULL,
	"manufacturer" VARCHAR(50) NOT NULL,
	"model" VARCHAR(255) NOT NULL,
	"year_of_manufacture" SMALLINT,
	PRIMARY KEY("id")
);




CREATE TABLE IF NOT EXISTS "clients" (
	"id" INTEGER NOT NULL UNIQUE GENERATED BY DEFAULT AS IDENTITY,
	"first_name" VARCHAR(30) NOT NULL,
	"last_name" VARCHAR(30) NOT NULL,
	"middle_name" VARCHAR(30),
	"phone_number" VARCHAR(20) NOT NULL,
	"email" VARCHAR(64),
	PRIMARY KEY("id")
);


CREATE INDEX "clients_index_0"
ON "clients" ("first_name", "last_name");
CREATE INDEX "clients_index_1"
ON "clients" ("phone_number");

CREATE TABLE IF NOT EXISTS "operations" (
	"id" INTEGER NOT NULL UNIQUE GENERATED BY DEFAULT AS IDENTITY,
	"price" INTEGER NOT NULL,
	PRIMARY KEY("id")
);




CREATE TABLE IF NOT EXISTS "engineers" (
	"id" INTEGER NOT NULL UNIQUE GENERATED BY DEFAULT AS IDENTITY,
	"first_name" VARCHAR(30) NOT NULL,
	"last_name" VARCHAR(30) NOT NULL,
	PRIMARY KEY("id")
);




CREATE TABLE IF NOT EXISTS "orders_operations" (
	"order_id" INTEGER NOT NULL UNIQUE GENERATED BY DEFAULT AS IDENTITY,
	"operation_id" INTEGER NOT NULL,
	"engineer_id" INTEGER NOT NULL,
	PRIMARY KEY("order_id")
);




CREATE TABLE IF NOT EXISTS "orders_parts" (
	"order_id" INTEGER NOT NULL UNIQUE GENERATED BY DEFAULT AS IDENTITY,
	"part_id" INTEGER NOT NULL,
	PRIMARY KEY("order_id")
);




CREATE TABLE IF NOT EXISTS "parts" (
	"id" INTEGER NOT NULL UNIQUE GENERATED BY DEFAULT AS IDENTITY,
	"name" VARCHAR(255) NOT NULL,
	"article number" INTEGER NOT NULL,
	"remains" SMALLINT NOT NULL,
	"price" INTEGER NOT NULL,
	PRIMARY KEY("id")
);




CREATE TABLE IF NOT EXISTS "users" (
	"id" INTEGER NOT NULL UNIQUE GENERATED BY DEFAULT AS IDENTITY,
	"login" VARCHAR(50) NOT NULL,
	"password_hash" VARCHAR(255) NOT NULL,
	"engineer_id" INTEGER,
	PRIMARY KEY("id")
);



ALTER TABLE "active_orders"
ADD FOREIGN KEY("id") REFERENCES "orders"("id")
ON UPDATE NO ACTION ON DELETE CASCADE;
ALTER TABLE "archive_orders"
ADD FOREIGN KEY("id") REFERENCES "orders"("id")
ON UPDATE NO ACTION ON DELETE CASCADE;
ALTER TABLE "orders"
ADD FOREIGN KEY("client_id") REFERENCES "clients"("id")
ON UPDATE NO ACTION ON DELETE CASCADE;
ALTER TABLE "orders"
ADD FOREIGN KEY("car_id") REFERENCES "cars"("id")
ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "orders_operations"
ADD FOREIGN KEY("engineer_id") REFERENCES "engineers"("id")
ON UPDATE NO ACTION ON DELETE CASCADE;
ALTER TABLE "orders_operations"
ADD FOREIGN KEY("operation_id") REFERENCES "operations"("id")
ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "orders_operations"
ADD FOREIGN KEY("order_id") REFERENCES "orders"("id")
ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "orders_parts"
ADD FOREIGN KEY("part_id") REFERENCES "parts"("id")
ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "orders_parts"
ADD FOREIGN KEY("order_id") REFERENCES "orders"("id")
ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "users"
ADD FOREIGN KEY("engineer_id") REFERENCES "engineers"("id")
ON UPDATE NO ACTION ON DELETE NO ACTION;